INSERT INTO site_settings (id, site_title_vi, site_description_vi, seo_keywords_vi, og_image_url, twitter_handle, github_url, linkedin_url, email, created_at, updated_at, site_title_en, site_description_en, seo_keywords_en, resume_url, phone) VALUES (1, 'Trần Minh Hiểu | AI Backend Engineer', 'AI Backend Engineer với kinh nghiệm xây dựng kiến trúc backend có khả năng mở rộng, nền tảng SaaS multi-tenant và ứng dụng AI end-to-end. Thành thạo thiết kế RAG pipeline và hệ thống xử lý bất đồng bộ hiệu suất cao.', 'Trần Minh Hiếu,AI Backend Engineer,RAG,LangChain,Multi-tenant SaaS', '', '', 'https://github.com/Tmh3101', 'https://linkedin.com/in/tmh3101', 'hieutm.site@gmail.com', '2026-03-15T17:03:18.365486+00:00', '2026-08-16T08:34:01.483691+00:00', 'Tran Minh Hieu | AI Backend Engineer', 'AI Backend Engineer with hands-on experience in building scalable backend architectures, multi-tenant SaaS platforms, and end-to-end AI applications. Proficient in designing advanced RAG pipelines and high-throughput asynchronous processing systems. Computer Science background with strong expertise in API security, data pipeline automation, and Web3 cross-chain integrations.', 'Tran Minh Hieu,AI Backend Engineer,RAG,LangChain,Multi-tenant SaaS', 'https://uhhmsyhsbcvfvilphwdk.supabase.co/storage/v1/object/public/portfolio-assets/cv/CV_TranMinhHieu.pdf', '+84 399 750 368');
INSERT INTO hero_section (id, greeting_vi, name, headline_vi, subheadline_vi, roles_vi, avatar_url, cta_primary_label_vi, cta_primary_href, cta_secondary_label_vi, cta_secondary_href, created_at, updated_at, greeting_en, headline_en, subheadline_en, roles_en, cta_primary_label_en, cta_secondary_label_en, subtitle_vi, subtitle_en, role1_label_vi, role1_label_en, role2_label_vi, role2_label_en, role3_label_vi, role3_label_en) VALUES (1, 'Xin chào, tôi là', 'Trần Minh Hiểu', 'AI Backend Engineer', 'Tôi xây dựng kiến trúc backend có khả năng mở rộng, nền tảng SaaS multi-tenant và ứng dụng AI end-to-end — từ RAG pipeline đến hệ thống xử lý bất đồng bộ hiệu suất cao.', 'RAG & LLM,Can Tho University,Computer Science', '/avatars/hieutm.jpg', 'Xem CV', 'https://uhhmsyhsbcvfvilphwdk.supabase.co/storage/v1/object/public/portfolio-assets/cv/CV_TranMinhHieu.pdf', 'Liên hệ', '#contact', '2026-03-15T17:07:04.237823+00:00', '2026-08-16T09:54:07.946292+00:00', 'Hi, I am', 'AI Backend Engineer', 'I build scalable backend architectures, multi-tenant SaaS platforms, and end-to-end AI apps — from RAG pipelines to high-throughput async systems.', 'RAG & LLM,Can Tho University,Computer Science', NULL, NULL, 'AI, Backend & Multi-tenant SaaS', 'AI, Backend & Multi-tenant SaaS', 'Tập trung Focus về AI / Backend', 'Focus on AI / Backend', 'Tốt nghiệp', 'Graduated', 'Chuyên ngành', 'Major');
INSERT INTO experience_section (id, eyebrow_vi, eyebrow_en, title1_vi, title1_en, title2_vi, title2_en, description_vi, description_en, current_role_label_vi, current_role_label_en, earlier_roles_label_vi, earlier_roles_label_en, earlier_roles_copy_vi, earlier_roles_copy_en, education_label_vi, education_label_en, highlights_label_vi, highlights_label_en, created_at, updated_at) VALUES (1, 'Hành trình', 'Journey', 'Kinh nghiệm', 'Professional', 'làm việc', 'Experience', 'Hành trình từ khi còn là sinh viên đến khi trở thành Backend Developer, tập trung vào việc xây dựng các hệ thống ổn định và có khả năng mở rộng.', 'A journey from student years to Backend Developer, focusing on building stable and scalable systems.', 'Vai trò hiện tại', 'Current role', 'Các chặng trước', 'Earlier roles', 'Những vai trò trước đó tạo nền cho cách tôi xây backend systems hôm nay.', 'The earlier roles that shaped how I approach backend systems today.', 'Học vấn', 'Education', 'Điểm chính', 'Highlights', '2026-03-17T07:48:51.662793+00:00', '2026-03-17T07:48:51.662793+00:00');
INSERT INTO skill_section (id, eyebrow_vi, eyebrow_en, title1_vi, title1_en, title2_vi, title2_en, description_vi, description_en, created_at, updated_at) VALUES (1, 'Kỹ năng', 'Skills', 'Công nghệ tôi dùng', 'Tech I work with', 'tôi sử dụng', 'Stack', 'Ngôn ngữ, framework, database và công cụ cloud tôi dùng để ship sản phẩm backend & AI.', 'Languages, frameworks, databases and cloud tooling I use to ship backend & AI products.', '2026-03-17T06:15:44.607856+00:00', '2026-08-16T07:51:38.152029+00:00');
INSERT INTO approach_section (id, eyebrow_vi, eyebrow_en, title1_vi, title1_en, title2_vi, title2_en, description_vi, description_en, note_label_vi, note_label_en, note_vi, note_en, created_at, updated_at) VALUES (1, 'About', 'About', 'Tôi tập trung vào', 'I focus on', 'backend systems', 'backend systems', 'Tôi là backend developer tập trung vào API design, system reliability và các service dễ maintain. Tôi thích các bài toán về data flow, performance, tích hợp hệ thống và những workflow có nhiều logic nghiệp vụ.', 'I am a backend developer focused on API design, system reliability, and maintainable services. I enjoy problems around data flow, performance, system integrations, and workflow-heavy business logic.', 'Role tôi đang nhắm tới', 'Roles I am targeting', 'Backend Developer / Backend Engineer ở các team cần service rõ ràng, ổn định và có khả năng mở rộng. Tôi cũng có hứng thú với AI automation và AI-powered workflows.', 'Backend Developer / Backend Engineer roles where I can help build clear, reliable, and scalable services. I also have a growing interest in AI automation and AI-powered workflows.', '2026-03-17T05:56:08.169847+00:00', '2026-03-17T05:57:48.533609+00:00');
INSERT INTO approaches (id, title_vi, subtitle_vi, description_vi, icon, sort_order, created_at, updated_at, title_en, subtitle_en, description_en) VALUES (2, 'Thiết kế API & service', 'API rõ ràng', 'Thiết kế API, contract và service layer rõ ràng để frontend, mobile hoặc hệ thống tích hợp có thể làm việc ổn định.', '', 0, '2026-03-17T05:59:15.492065+00:00', '2026-08-16T07:51:38.837996+00:00', 'API & service design', 'Clear APIs', 'I design APIs, contracts, and service layers that are clear enough for frontend, mobile, and external integrations to work against confidently.');
INSERT INTO approaches (id, title_vi, subtitle_vi, description_vi, icon, sort_order, created_at, updated_at, title_en, subtitle_en, description_en) VALUES (3, 'Luồng dữ liệu & tích hợp', 'Data flow', 'Xây dựng pipeline dữ liệu, hàng đợi bất đồng bộ và tích hợp hệ thống giúp luân chuyển dữ liệu ổn định giữa các service.', '', 1, '2026-03-17T05:59:58.41027+00:00', '2026-08-16T07:51:38.837996+00:00', 'Data flow & integration', 'Data flow', 'I build data pipelines, async queues, and system integrations that move data reliably between services.');
INSERT INTO approaches (id, title_vi, subtitle_vi, description_vi, icon, sort_order, created_at, updated_at, title_en, subtitle_en, description_en) VALUES (4, 'Tự động hóa AI & RAG', 'AI & RAG', 'Thiết kế RAG pipeline (Gemini + pgvector), LangChain và các workflow AI giúp sản phẩm vận hành thông minh hơn.', '', 2, '2026-03-17T06:00:21.343968+00:00', '2026-08-16T07:51:38.837996+00:00', 'AI automation & RAG', 'AI & RAG', 'I design RAG pipelines (Gemini + pgvector), LangChain, and AI workflows that make products smarter.');
INSERT INTO stats (id, label_vi, value, suffix, sort_order, created_at, updated_at, label_en, copy_vi, copy_en, icon) VALUES (1, 'Năm kinh nghiệm', 2, '+', 0, '2026-03-16T16:28:42.41604+00:00', '2026-03-16T16:28:42.41604+00:00', 'Years of experience', 'Từ công việc thực tập đến việc triển khai sản phẩm phía máy chủ trong môi trường thực tế.', 'From internship work to deploying backend products in a real-world environment.', 'Rocket');
