INSERT INTO stats (id, label_vi, value, suffix, sort_order, created_at, updated_at, label_en, copy_vi, copy_en, icon) VALUES (2, 'Dự án AI', 3, '+', 1, '2026-03-16T16:31:03.027016+00:00', '2026-08-16T07:51:38.456299+00:00', 'AI Projects', 'RAG pipeline, LangChain và các workflow tích hợp AI thực tế.', 'RAG pipelines, LangChain and real-world AI integration workflows.', 'Sparkles');
