INSERT INTO experiences (id, company, role_vi, location_vi, start_date, end_date, is_current, description_vi, highlights_vi, technologies, sort_order, created_at, updated_at, role_en, location_en, description_en, highlights_en, type) VALUES (5, 'TITOPS VIETNAM CO., LTD.', 'Full-stack Developer', 'Việt Nam', '2025-09-01', '2025-11-01', false, 'Giftcards - Giải pháp quà tặng doanh nghiệp. Tích hợp cổng thanh toán DNPAY, tối ưu luồng đặt hàng.', 'Tích hợp gateway DNPAY Merchant,Cải thiện luồng đặt hàng + tính năng retry thanh toán', 'NestJS,MongoDB,Redis,ReactJS', 0, '2026-08-16T06:39:44.423112+00:00', '2026-08-16T06:39:44.423112+00:00', 'Full-stack Developer', 'Vietnam', 'Giftcards - Corporate Gift Solution. DNPAY payment integration, order flow optimization.', 'DNPAY Merchant gateway integration,Order flow optimization + payment retry feature', 'work');
